command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
Set-Location -LiteralPath $repo
& git fetch origin work/failure-propagation-native-preflight-20261005 --no-tags --prune
if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
$temp=Join-Path $env:RUNNER_TEMP ("infra-direct-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp 8a53cf9430ba56ba74fb69f7d374846fc34843bf
  if($LASTEXITCODE -ne 0){throw "candidate worktree failed"}
  Set-Location -LiteralPath $temp
  & git diff --check ef8e2d7a65c03c3727aae625facaf6305d7d9841 8a53cf9430ba56ba74fb69f7d374846fc34843bf
  if($LASTEXITCODE -ne 0){throw "git diff check failed"}
  $py=@(
    "tools\winui\run_checks.py",
    "tools\winui\resolve_validation_scope.py",
    "tests\winui\test_remote_windows_task_contract.py",
    "tests\winui\test_remote_failure_classifier.py",
    "tests\winui\test_validation_scope_contract.py",
    "tests\winui\test_build_environment_contract.py"
  )
  & python -X utf8 tools\winui\check_python_static.py @py
  if($LASTEXITCODE -ne 0){throw "changed Python static failed"}
  & python -X utf8 -m unittest tests.winui.test_remote_windows_task_contract tests.winui.test_remote_failure_classifier tests.winui.test_validation_scope_contract tests.winui.test_build_environment_contract
  if($LASTEXITCODE -ne 0){throw "infra contracts failed"}
  $sw=[Diagnostics.Stopwatch]::StartNew()
  & cmd /c app\winui\build.cmd Release Compile m23_drag.cpp
  $compileCode=$LASTEXITCODE
  $sw.Stop()
  Write-Host ("DIRECT_NATIVE_COMPILE_SECONDS={0:N1}" -f $sw.Elapsed.TotalSeconds)
  if($compileCode -ne 0){throw "direct native compile preflight failed"}
  Write-Host "DIRECT_INFRA_AND_NATIVE_PREFLIGHT=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
